const express = require('express');
const { SQSClient, SendMessageCommand } = require('@aws-sdk/client-sqs');
const { v4: uuidv4 } = require('uuid');
const { db } = require('../models/database');

const app = express();
app.use(express.json());

const sqsClient = new SQSClient({ region: process.env.AWS_REGION || 'us-east-1' });
const PAYOUT_QUEUE_URL = process.env.PAYOUT_FIFO_QUEUE_URL;

app.post('/api/v1/payouts/dispatch', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { sourceAccountId, destinationRouting, destinationAccount, amount } = req.body;

  if (!sourceAccountId || !amount || amount <= 0) {
    return res.status(400).json({ error: 'Invalid payout parameters' });
  }

  // Verify that the authenticated user has withdrawal authorization on the source account
  const account = await db.accounts.findOne({
    where: {
      accountId: sourceAccountId,
      ownerUserId: req.user.id
    }
  });

  if (!account) {
    return res.status(403).json({ error: 'Access denied: unauthorized source account' });
  }

  const messagePayload = {
    payoutId: uuidv4(),
    sourceAccountId: account.accountId,
    initiatorUserId: req.user.id,
    destinationRouting,
    destinationAccount,
    amount,
    currency: 'USD',
    requestedAt: new Date().toISOString()
  };

  const command = new SendMessageCommand({
    QueueUrl: PAYOUT_QUEUE_URL,
    MessageBody: JSON.stringify(messagePayload),
    MessageGroupId: account.accountId,
    MessageDeduplicationId: `${account.accountId}_${Date.now()}`
  });

  try {
    const response = await sqsClient.send(command);
    res.status(202).json({
      status: 'QUEUED',
      messageId: response.MessageId,
      payoutId: messagePayload.payoutId
    });
  } catch (err) {
    res.status(500).json({ error: 'Failed to enqueue payout transaction' });
  }
});

app.listen(3000);
